SELECT INQUIRY_ID AS inquiryId, INQUIRY_COMPANY_NAME AS companyName, INQUIRY_APPLICANT_NAME AS applicantName, INQUIRY_EMAIL AS email, INQUIRY_CONTACT AS contact, INQUIRY_TYPE AS inquiryType, INQUIRY_CONTENT AS content, IFNULL(STATUS, 'PENDING') AS status, ANSWERED_AT AS answeredAt, CREATED_AT AS createdAt FROM COM_INTRO_EMAIL WHERE 1=1
AND STATUS = #{status}
AND ( INQUIRY_COMPANY_NAME LIKE CONCAT('%', #{keyword}, '%') OR INQUIRY_APPLICANT_NAME LIKE CONCAT('%', #{keyword}, '%') OR INQUIRY_EMAIL LIKE CONCAT('%', #{keyword}, '%') OR INQUIRY_CONTENT LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY INQUIRY_ID DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM COM_INTRO_EMAIL WHERE 1=1
AND STATUS = #{status}
AND ( INQUIRY_COMPANY_NAME LIKE CONCAT('%', #{keyword}, '%') OR INQUIRY_APPLICANT_NAME LIKE CONCAT('%', #{keyword}, '%') OR INQUIRY_EMAIL LIKE CONCAT('%', #{keyword}, '%') OR INQUIRY_CONTENT LIKE CONCAT('%', #{keyword}, '%') )
